<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import {formatTimestamp} from '../../shared/time'
import Pagination from '../../shared/components/Pagination.vue'
import DispatchDialog from './DispatchDialog.vue'
import './intelligence.css'
type Delivery={id:string;clue_id:string;parent_id:string|null;sender_name:string;recipient_name:string;objective:string;due_date:string|null;status:string;version:number;allow_station:boolean;assignee_id:string|null;assignee_name:string|null;snapshot:{title:string;summary:string;source:string;reference_no:string|null;priority:string};disposition_text:string;feedback_text:string;result_code:string|null;overdue:boolean;created_at:string}
type Event={id:string;action:string;note:string;actor:string;organization:string;created_at:string;payload:Record<string,string>|null}
type Detail={delivery:Delivery;children:Delivery[];children_total:number;children_page:number;pending_children:number;can_handle:boolean;can_resolve:boolean;actor_id:string;events:{items:Event[];total:number;page:number}}
const props=defineProps<{scope:'received'|'sent'}>()
const {api,command,can,captureSession}=useWorkspace(),requests=createLatestRequests(api)
const rows=ref<Delivery[]>([]),total=ref(0),page=ref(1),keyword=ref(''),status=ref(''),mine=ref(false),overdue=ref(false),busy=ref(false),error=ref(''),notice=ref(''),detail=ref<Detail|null>(null),dispatching=ref(false),note=ref(''),disposition=ref(''),feedback=ref(''),result=ref('NO_FINDING'),reviewNote=ref('')
const handlers=ref<{id:string;username:string}[]>([]),handoffTarget=ref(''),handoffNote=ref(''),handingOff=ref(false)
let applied={keyword:'',status:'',mine:false,overdue:false}
const stepFor:Record<string,number>={OPEN:2,PROCESSING:3,RETURNED:3,PENDING_REVIEW:4,CLOSED:5}
const labels:Record<string,string>={OPEN:'待接收',PROCESSING:'处置中',PENDING_REVIEW:'待复核',RETURNED:'退回补充',CLOSED:'已办结'}
const actions:Record<string,string>={REASSIGN:'转交承办',DISPATCH:'下发',ACCEPT:'接收承办',PROGRESS:'登记处置',FEEDBACK:'提交反馈',RETURN:'退回补充',CLOSE:'复核办结'}
const results:Record<string,string>={VERIFIED:'已核实',NO_FINDING:'未发现',INSUFFICIENT:'信息不足',DUPLICATE:'重复线索',TRANSFER:'转其他单位',CONTINUE:'待继续核查'}
async function load(target=page.value,filters=applied){const response=await requests.latest<{items:Delivery[];total:number}>('list','/intelligence/deliveries/search',{method:'POST',body:JSON.stringify({scope:props.scope,...filters,status:filters.status||null,page:target})});rows.value=response.items;total.value=response.total;page.value=target;applied={...filters}}
async function act(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function open(id:string,eventPage=1,childPage=1){const response=await requests.latest<Detail>('detail',`/intelligence/deliveries/${id}?page=${eventPage}&child_page=${childPage}`);const changed=detail.value?.delivery.id!==response.delivery.id||detail.value?.delivery.version!==response.delivery.version;detail.value=response;if(changed){disposition.value=response.delivery.disposition_text;feedback.value=response.delivery.feedback_text;result.value=response.delivery.result_code||'NO_FINDING'}}
async function change(action:'accept'|'progress'|'feedback'|'resolve',resolution?:'RETURN'|'CLOSE'){if(!detail.value)return;await act(async()=>{const current=captureSession(),row=detail.value!.delivery;const body={version:row.version,...(action==='progress'?{note:note.value}:action==='feedback'?{disposition:disposition.value,feedback:feedback.value,result:result.value}:action==='resolve'?{action:resolution,note:reviewNote.value}:{})};await command('delivery-'+row.id+'-'+action,`/intelligence/deliveries/${row.id}/${action}`,body);if(!current())return;notice.value='流转处理已记录';note.value='';reviewNote.value='';await Promise.all([open(row.id),load()])})}
async function handoff(){if(!detail.value)return;await act(async()=>{const row=detail.value!.delivery;await command('delivery-handoff-'+row.id,`/intelligence/deliveries/${row.id}/reassign`,{version:row.version,assignee_id:handoffTarget.value,note:handoffNote.value});handingOff.value=false;handoffTarget.value='';handoffNote.value='';await Promise.all([open(row.id),load()])})}
async function chooseHandoff(){await act(async()=>{handlers.value=await requests.latest('handlers','/intelligence/delivery-handlers');handingOff.value=true})}
async function dispatched(){dispatching.value=false;if(detail.value)await act(async()=>{await Promise.all([open(detail.value!.delivery.id),load()])})}
onMounted(()=>{void act(()=>load(1))});onBeforeUnmount(()=>requests.dispose())
</script>
<template><div class="page-list intelligence-flow"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><section class="card"><form class="system-search" @submit.prevent="act(()=>load(1,{keyword,status,mine,overdue}))"><label>检索线索<input v-model="keyword" maxlength="100" placeholder="编号、标题或办理要求"></label><label>办理状态<select v-model="status"><option value="">全部状态</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><label v-if="scope==='received'" class="check-label"><input v-model="mine" type="checkbox">仅我承办</label><label class="check-label"><input v-model="overdue" type="checkbox">仅逾期未办结</label><button :disabled="busy">查询</button><button type="button" class="secondary" :disabled="busy" @click="keyword='';status='';mine=false;overdue=false;act(()=>load(1,{keyword:'',status:'',mine:false,overdue:false}))">重置</button></form><div class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>线索编号</th><th>标题</th><th>下发单位</th><th>接收单位</th><th>承办人</th><th>反馈期限</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{row.snapshot.reference_no||'历史线索'}}</td><td>{{row.snapshot.title}}</td><td>{{row.sender_name}}</td><td>{{row.recipient_name}}</td><td>{{row.assignee_name||'待接收'}}</td><td>{{row.due_date||'未设置'}}<span v-if="row.overdue" class="flow-overdue">逾期</span></td><td>{{labels[row.status]}}</td><td><button class="link" :disabled="busy" @click="act(()=>open(row.id))">查看办理</button></td></tr></tbody></table><p v-if="!rows.length&&!busy" class="empty">暂无{{scope==='received'?'收到':'下发'}}的线索</p></div><Pagination :page="page" :total="total" :loading="busy" @change="act(()=>load($event))"/></section>
<section v-if="detail" class="card flow-detail"><div class="page-toolbar"><h2>{{detail.delivery.snapshot.title}}</h2><button class="link" @click="detail=null">关闭详情</button></div><fieldset class="flow-fields" :disabled="busy"><div class="flow-stages"><span v-for="(item,index) in ['录入 / 导入','核验','下发','接收处置','反馈','复核办结']" :key="item" :class="{'is-current':index===stepFor[detail.delivery.status]}">{{item}}</span></div><dl class="flow-overview"><div><dt>流转状态</dt><dd>{{labels[detail.delivery.status]}}</dd></div><div><dt>下发单位</dt><dd>{{detail.delivery.sender_name}}</dd></div><div><dt>接收单位</dt><dd>{{detail.delivery.recipient_name}}</dd></div><div><dt>承办人</dt><dd>{{detail.delivery.assignee_name||'待接收'}}</dd></div><div><dt>反馈期限</dt><dd>{{detail.delivery.due_date||'未设置'}}</dd></div><div><dt>下发限制</dt><dd>{{detail.delivery.allow_station?'允许派出所':'禁止派出所，下级不得放宽'}}</dd></div></dl><p><b>来源：</b>{{detail.delivery.snapshot.source}}</p><p class="flow-text"><b>线索内容：</b>{{detail.delivery.snapshot.summary}}</p><p class="flow-text"><b>办理要求：</b>{{detail.delivery.objective}}</p>
<div v-if="detail.can_handle" class="detail"><button v-if="can('intelligence.dispatch')&&['OPEN','PROCESSING','RETURNED'].includes(detail.delivery.status)" class="secondary" :disabled="busy" @click="chooseHandoff">指定 / 转交承办人</button><form v-if="handingOff" @submit.prevent="handoff"><label>新承办人<select v-model="handoffTarget" required><option value="" disabled>选择本单位处置人员</option><option v-for="person in handlers.filter(row=>row.id!==detail?.delivery.assignee_id)" :key="person.id" :value="person.id">{{person.username}}</option></select></label><label>转交原因<textarea v-model="handoffNote" required maxlength="5000"></textarea></label><div class="actions"><button :disabled="busy">确认转交</button><button type="button" class="secondary" @click="handingOff=false">取消转交</button></div></form><button v-if="detail.delivery.status==='OPEN'&&can('intelligence.dispose')" :disabled="busy" @click="change('accept')">接收并由我承办</button><template v-if="['PROCESSING','RETURNED'].includes(detail.delivery.status)"><button v-if="can('intelligence.dispatch')" class="secondary" :disabled="busy" @click="dispatching=true">继续下发下级单位</button><template v-if="can('intelligence.dispose')&&detail.delivery.assignee_id===detail.actor_id"><form @submit.prevent="change('progress')"><h3>处置记录</h3><label>本次处置<textarea v-model="note" maxlength="5000" required></textarea></label><button :disabled="busy">保存处置记录</button></form><form class="detail" @submit.prevent="change('feedback')"><h3>提交处置反馈</h3><label>处置经过<textarea v-model="disposition" required maxlength="5000"></textarea></label><label>反馈内容<textarea v-model="feedback" required maxlength="5000"></textarea></label><label>处置结果<select v-model="result"><option v-for="(label,key) in results" :key="key" :value="key">{{label}}</option></select></label><p v-if="detail.pending_children>0" class="muted">下级线索尚未全部办结，需先复核下级反馈后才能汇总上报。</p><button :disabled="busy||detail.pending_children>0">向上级提交反馈</button></form></template></template></div>
<div v-if="detail.delivery.feedback_text" class="detail"><h3>当前反馈</h3><p class="flow-text"><b>处置经过：</b>{{detail.delivery.disposition_text}}</p><p class="flow-text"><b>反馈内容：</b>{{detail.delivery.feedback_text}}</p><p><b>结果：</b>{{results[detail.delivery.result_code||'']||'未填写'}}</p></div><form v-if="detail.can_resolve&&detail.delivery.status==='PENDING_REVIEW'&&can('intelligence.review')" class="detail" @submit.prevent="change('resolve','CLOSE')"><h3>复核下级反馈</h3><label>复核意见<textarea v-model="reviewNote" maxlength="5000" required></textarea></label><div class="actions"><button :disabled="busy">复核办结</button><button type="button" class="secondary" :disabled="busy||!reviewNote.trim()" @click="change('resolve','RETURN')">退回补充</button></div></form>
<section v-if="detail.children_total" class="detail"><h3>下级办理进度</h3><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>接收单位</th><th>状态</th><th>反馈期限</th><th>操作</th></tr></thead><tbody><tr v-for="(child,index) in detail.children" :key="child.id"><td class="row-number">{{(detail.children_page-1)*20+index+1}}</td><td>{{child.recipient_name}}</td><td>{{labels[child.status]}}</td><td>{{child.due_date||'未设置'}}</td><td><button class="link" @click="act(()=>open(child.id))">查看办理</button></td></tr></tbody></table></div><Pagination :page="detail.children_page" :total="detail.children_total" :loading="busy" @change="act(()=>open(detail!.delivery.id,detail!.events.page,$event))"/></section>
<section class="detail"><h3>流转与反馈历史</h3><ol class="flow-timeline"><li v-for="event in detail.events.items" :key="event.id"><strong>{{actions[event.action]||event.action}}</strong><small>{{formatTimestamp(event.created_at)}} · {{event.organization}} · {{event.actor}}</small><p class="flow-text">{{event.note}}</p><template v-if="event.action==='FEEDBACK'&&event.payload"><p class="flow-text">处置经过：{{event.payload.disposition}}</p><p class="flow-text">反馈内容：{{event.payload.feedback}}</p></template></li></ol><Pagination :page="detail.events.page" :total="detail.events.total" :loading="busy" @change="act(()=>open(detail!.delivery.id,$event))"/></section></fieldset></section>
<DispatchDialog v-if="dispatching&&detail" :parent-id="detail.delivery.id" :version="detail.delivery.version" :due-date="detail.delivery.due_date" :allow-station="detail.delivery.allow_station" :important="detail.delivery.snapshot.priority==='IMPORTANT'" @close="dispatching=false" @saved="dispatched"/>
</div></template>
